 *
 * ---------------------------------------------------------------------------
 * SHARED: filesystem handler - mounts the BlueSCSI/ZuluSCSI Toolbox shared
 * folder as an AmigaDOS volume so native tools (Copy, List, DOpus, Workbench)
 * can use it instead of SDTransfer's one-file download.
 *
 * PHASE 3: read path. Implements LOCATE/FREE_LOCK/COPY_DIR/PARENT, EXAMINE_
 * OBJECT/NEXT, FINDINPUT/READ/SEEK/END, INFO, CURRENT_VOLUME. The write path
 * (FINDOUTPUT/WRITE) and the firmware-unsupported ops (DELETE/RENAME/...) are
 * still stubbed -> Phase 4.
 *
 * PHASE 6 (firmware v2026.04.27+): subdirectories via the working-directory
 * metadata subcommands (SET/GET_WORKING_DIR, CAP_SET_WORKING_DIR). Locks carry
 * a path relative to the share root; every directory-scoped operation first
 * points the device's (global, persistent) working dir at gBaseDir/rel. On
 * older firmware everything degrades to the previous flat model. The firmware
 * caps SET_WORKING_DIR at 63 chars, which bounds base-dir + tree depth.
 * NOTE: the working dir is device-global - don't run SDTransfer (or another
 * navigating client) on the same unit while SHARED: is mounted.
 *
 * Startup convention + FileInfoBlock/lock details verified against fat95-3.23
 * (src/fat95.s): fib_FileName is a BCPL string (length byte + chars);
 * fib_DirEntryType = 1 (root) / -3 (file).
 *
 * BUILD: -nostartfiles. hstart.s provides _start at hunk offset 0 and jumps to
 * handlerMain. Links scsi.o (libc-free) but NOT common.o (no Intuition).
 */
#include <exec/types.h>
#include <exec/execbase.h>
#include <exec/memory.h>
#include <exec/ports.h>
#include <dos/dos.h>
#include <dos/dosextens.h>
#include <dos/filehandler.h>
#include <proto/exec.h>
#include <proto/dos.h>
#include <proto/utility.h>
#include "toolbox.h"

#define ID_SHARED_DISK 0x53484152UL   /* 'SHAR' */

__attribute__((used)) static const char ver[] = "$VER: sharedfs 1.8.2 (2.10.2026)";

/* With -nostartfiles we provide the library bases ourselves. */
struct ExecBase *SysBase = NULL;
struct DosLibrary *DOSBase = NULL;
struct Library *UtilityBase = NULL;   /* scsi.c (and we) use utility Str* fns */

static struct Process *gProc = NULL;
static BPTR gVolBptr = 0;             /* BPTR to our volume DosList node */
static struct DosList *gVol = NULL;   /* DLT_VOLUME node (Workbench disk icon) */
static LONG gUnit = 0;

/* Working-directory state (CAP_SET_WORKING_DIR firmware). gBaseDir is the
   device default (e.g. "/shared"); relative paths hang below it. gCurAbs
   mirrors what the device's working dir was last set to, so navTo can skip
   redundant SET commands. gListedDir says which relative dir the global
   'files' array currently describes. */
static int gHaveDirs = 0;
static char gBaseDir[80];
static char gCurAbs[80];
static char gListedDir[64];
static int gListedValid = 0;

/* A lock = a FileLock plus our per-object bookkeeping (fl_ must be first). */
struct MyLock
{
   struct FileLock fl;
   LONG  isFile;      /* 0 = directory, 1 = file */
   LONG  index;       /* toolbox file index within its dir (file) */
   ULONG fsize;       /* file size in bytes (file) */
   LONG  exNext;      /* EXAMINE_NEXT cursor (dir) */
   char  dir[64];     /* rel path: the dir itself (dir) / parent dir (file) */
   char  name[40];    /* leaf name ("" = root) */
};

/* An open file. Read mode uses index/fsize/pos; write mode streams 512-byte
   blocks to the toolbox upload protocol (PREP done at open, END at close). */
struct MyFH
{
   LONG  isWrite;     /* 0 = read, 1 = write */
   char  dir[64];     /* rel dir the file lives in (working dir for reads) */
   /* read */
   LONG  index;
   ULONG fsize;
   ULONG pos;
   /* write */
   ULONG wblock;      /* next 512-byte block index */
   ULONG wbuflen;     /* bytes currently buffered in wbuf */
   UBYTE wbuf[512];
};

/* ---- small libc-free string helpers ------------------------------------ */

static int cLen(const char *s)
{
   int n = 0;
   while (s[n])
      n++;
   return n;
}

static void cCopy(char *d, const char *s, int max)
{
   int i = 0;
   while (s[i] && i < max - 1)
   {
      d[i] = s[i];
      i++;
   }
   d[i] = '\0';
}

/* Write a BCPL string (length byte + chars) for fib_FileName / fib_Comment. */
static void putBStr(UBYTE *dest, const char *src, int maxchars)
{
   int n = cLen(src);
   int i;
   if (n > maxchars)
      n = maxchars;
   dest[0] = (UBYTE)n;
   for (i = 0; i < n; i++)
      dest[1 + i] = (UBYTE)src[i];
}

/* Convert a BSTR (BPTR) name to a C string leaf: strip any "VOLUME:" prefix
   and a leading '/'. An empty result means the volume root. */
static void leafFromBStr(BPTR bname, char *out, int max)
{
   UBYTE *bp = (UBYTE *)BADDR(bname);
   int len = bp ? bp[0] : 0;
   int start = 0;
   int i, j;

   for (i = 0; i < len; i++)        /* skip past a colon, if any */
   {
      if (bp[1 + i] == ':')
         start = i + 1;
   }
   if (start < len && bp[1 + start] == '/')
      start++;

   for (i = start, j = 0; i < len && j < max - 1; i++, j++)
      out[j] = (char)bp[1 + i];
   out[j] = '\0';
}

/* ---- relative-path helpers --------------------------------------------- */

/* Strip the last component of a rel path in place ("a/b" -> "a", "a" -> ""). */
static void parentOf(char *dir)
{
   int i = cLen(dir);
   while (i > 0 && dir[i - 1] != '/')
      i--;
   if (i > 0)
      i--;                                        /* also drop the '/' */
   dir[i] = '\0';
}

/* Last component of a rel path ("a/b" -> "b", "" -> ""). */
static const char *leafOf(const char *dir)
{
   int i = cLen(dir);
   while (i > 0 && dir[i - 1] != '/')
      i--;
   return dir + i;
}

/* Append a component to a rel path ("a" + "b" -> "a/b"). 0 or DOS error. */
static LONG catAppend(char *dir, const char *comp, int max)
{
   int l = cLen(dir);
   if (l + (l ? 1 : 0) + cLen(comp) >= max)
      return ERROR_INVALID_COMPONENT_NAME;
   if (l)
      dir[l++] = '/';
   cCopy(dir + l, comp, max - l);
   return 0;
}

/* ---- device working-directory navigation ------------------------------- */

/* Point the device's working directory at gBaseDir/rel. Without the working-
   dir capability only the root ("") exists. Returns 0 or a DOS error. */
static LONG navTo(const char *rel)
{
   char abs[160];

   if (!gHaveDirs)
      return rel[0] ? ERROR_DIR_NOT_FOUND : 0;

   cCopy(abs, gBaseDir, sizeof(abs));
   if (rel[0])
   {
      int l = cLen(abs);
      if (l + 1 + cLen(rel) >= (int)sizeof(abs))
         return ERROR_INVALID_COMPONENT_NAME;
      abs[l] = '/';
      cCopy(abs + l + 1, rel, sizeof(abs) - l - 1);
   }
   if (cLen(abs) > TOOLBOX_MAX_WD_PATH - 1)       /* firmware 63-char limit */
      return ERROR_INVALID_COMPONENT_NAME;

   if (Stricmp((STRPTR)abs, (STRPTR)gCurAbs) == 0)
      return 0;
   if (Toolbox_Set_Working_Dir(abs) != 0)
      return ERROR_DIR_NOT_FOUND;
   cCopy(gCurAbs, abs, sizeof(gCurAbs));
   gListedValid = 0;
   return 0;
}

/* Make the global 'files' array describe relative dir 'rel' (cached). */
static LONG listDir(const char *rel)
{
   LONG err;

   if (gListedValid && Stricmp((STRPTR)gListedDir, (STRPTR)rel) == 0)
      return 0;
   gListedValid = 0;
   if ((err = navTo(rel)) != 0)
      return err;
   Toolbox_List_Files(0);
   if (filecount < 0)
      return ERROR_NOT_A_DOS_DISK;
   cCopy(gListedDir, rel, sizeof(gListedDir));
   gListedValid = 1;
   return 0;
}

/* Find 'leaf' in relative dir 'dirRel' (case-insensitive). Returns 1 found
   (type/idx/size filled), 0 not found, or a negated DOS error. On flat
   (no-capability) firmware, directory entries are invisible as before. */
static LONG findEntry(const char *dirRel, const char *leaf,
                      LONG *type, LONG *idx, ULONG *size)
{
   LONG err = listDir(dirRel);
   int i;

   if (err)
      return -err;
   for (i = 0; i < filecount; i++)
   {
      if (!gHaveDirs && files[i].Type != BLUESCSI_FILE)
         continue;
      if (Stricmp((STRPTR)files[i].Name, (STRPTR)leaf) == 0)
      {
         *type = files[i].Type;
         *idx = files[i].Index;
         *size = files[i].Size;
         return 1;
      }
   }
   return 0;
}

/* Resolve an AmigaDOS path (BSTR 'bname', relative to lock 'base') into a
   validated parent dir 'outDir' (rel to the share root, all intermediate
   components checked to exist) and an unvalidated final component 'outLeaf'
   ("" = the directory itself). AmigaDOS semantics: ':' resets to the root,
   each leading (or doubled) '/' goes up one level. 0 or DOS error. */
static LONG resolvePath(struct MyLock *base, BPTR bname,
                        char *outDir, char *outLeaf)
{
   UBYTE *bp = (UBYTE *)BADDR(bname);
   int len = bp ? bp[0] : 0;
   int i = 0, j;

   if (base)
      cCopy(outDir, base->dir, 64);
   else
      outDir[0] = '\0';
   outLeaf[0] = '\0';

   for (j = 0; j < len; j++)
   {
      if (bp[1 + j] == ':')
      {
         i = j + 1;
         outDir[0] = '\0';
      }
   }

   while (i < len && bp[1 + i] == '/')            /* leading '/' = parent */
   {
      if (outDir[0] == '\0')
         return ERROR_OBJECT_NOT_FOUND;           /* above the root */
      parentOf(outDir);
      i++;
   }

   while (i < len)
   {
      char comp[40];
      int cl = 0;
      int more;

      while (i < len && bp[1 + i] != '/')
      {
         if (cl < (int)sizeof(comp) - 1)
            comp[cl++] = (char)bp[1 + i];
         i++;
      }
      comp[cl] = '\0';
      more = (i < len);
      if (more)
         i++;                                     /* skip the '/' */

      if (!more)
      {
         cCopy(outLeaf, comp, 40);
         break;
      }

      if (cl == 0)                                /* "a//b": extra '/' = parent */
      {
         if (outDir[0] == '\0')
            return ERROR_OBJECT_NOT_FOUND;
         parentOf(outDir);
      }
      else
      {
         LONG t, idx;
         ULONG sz;
         LONG r = findEntry(outDir, comp, &t, &idx, &sz);
         if (r < 0)
            return -r;
         if (r == 0 || t != BLUESCSI_DIR)
            return ERROR_DIR_NOT_FOUND;
         if (catAppend(outDir, comp, 64) != 0)
            return ERROR_INVALID_COMPONENT_NAME;
      }
   }
   return 0;
}

/* ---- locks ------------------------------------------------------------- */

static BPTR makeLock(LONG isFile, LONG index, ULONG fsize,
                     const char *dir, const char *name)
{
   struct MyLock *lk = AllocVec(sizeof(struct MyLock), MEMF_CLEAR | MEMF_PUBLIC);
   if (!lk)
      return 0;
   lk->fl.fl_Key = index;
   lk->fl.fl_Access = ACCESS_READ;
   lk->fl.fl_Task = &gProc->pr_MsgPort;
   lk->fl.fl_Volume = gVolBptr;
   lk->isFile = isFile;
   lk->index = index;
   lk->fsize = fsize;
   lk->exNext = 0;
   if (dir)
      cCopy(lk->dir, dir, sizeof(lk->dir));
   if (name)
      cCopy(lk->name, name, sizeof(lk->name));
   return MKBADDR(lk);
}

static void freeLock(BPTR lock)
{
   struct MyLock *lk = (struct MyLock *)BADDR(lock);
   if (lk)
      FreeVec(lk);
}

/* ---- packet handlers --------------------------------------------------- */

static void doLocateObject(struct DosPacket *pkt)
{
   struct MyLock *base = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg1);
   char dir[64];
   char leaf[40];
   LONG err, t, idx;
   ULONG size;
   BPTR lk;

   if ((err = resolvePath(base, pkt->dp_Arg2, dir, leaf)) != 0)
   {
      pkt->dp_Res1 = 0;
      pkt->dp_Res2 = err;
      return;
   }

   if (leaf[0] == '\0')                          /* the directory itself */
   {
      lk = makeLock(0, 0, 0, dir, leafOf(dir));
      pkt->dp_Res1 = (LONG)lk;
      pkt->dp_Res2 = lk ? 0 : ERROR_NO_FREE_STORE;
      return;
   }

   {
      LONG r = findEntry(dir, leaf, &t, &idx, &size);
      if (r < 0)
         { pkt->dp_Res1 = 0; pkt->dp_Res2 = -r; return; }
      if (r == 0)
         { pkt->dp_Res1 = 0; pkt->dp_Res2 = ERROR_OBJECT_NOT_FOUND; return; }
   }

   if (t == BLUESCSI_DIR)
   {
      char full[64];
      cCopy(full, dir, sizeof(full));
      if (catAppend(full, leaf, sizeof(full)) != 0)
         { pkt->dp_Res1 = 0; pkt->dp_Res2 = ERROR_INVALID_COMPONENT_NAME; return; }
      lk = makeLock(0, 0, 0, full, leaf);
   }
   else
   {
      lk = makeLock(1, idx, size, dir, leaf);
   }
   pkt->dp_Res1 = (LONG)lk;
   pkt->dp_Res2 = lk ? 0 : ERROR_NO_FREE_STORE;
}

static void doCopyDir(struct DosPacket *pkt)
{
   struct MyLock *src = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg1);
   BPTR lk;
   if (!src) { pkt->dp_Res1 = 0; return; }       /* dup of root (0) -> root */
   lk = makeLock(src->isFile, src->index, src->fsize, src->dir, src->name);
   pkt->dp_Res1 = (LONG)lk;
   pkt->dp_Res2 = lk ? 0 : ERROR_NO_FREE_STORE;
}

static void doParent(struct DosPacket *pkt)
{
   struct MyLock *lk = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg1);
   BPTR par = 0;

   pkt->dp_Res2 = 0;
   if (lk && lk->isFile)                          /* file -> its dir */
   {
      par = makeLock(0, 0, 0, lk->dir, leafOf(lk->dir));
      if (!par)
         pkt->dp_Res2 = ERROR_NO_FREE_STORE;
   }
   else if (lk && lk->dir[0])                     /* subdir -> parent dir */
   {
      char pdir[64];
      cCopy(pdir, lk->dir, sizeof(pdir));
      parentOf(pdir);
      par = makeLock(0, 0, 0, pdir, leafOf(pdir));
      if (!par)
         pkt->dp_Res2 = ERROR_NO_FREE_STORE;
   }
   /* root (or zero lock) -> no parent */
   pkt->dp_Res1 = (LONG)par;
}

static void fillDirFib(struct FileInfoBlock *fib, const char *name, LONG entrytype)
{
   fib->fib_DiskKey = 0;
   fib->fib_DirEntryType = entrytype;             /* 1 = root, 2 = user dir */
   fib->fib_EntryType = entrytype;
   putBStr((UBYTE *)fib->fib_FileName, name, 30);
   fib->fib_Protection = 0;
   fib->fib_Size = 0;
   fib->fib_NumBlocks = 0;
   fib->fib_Comment[0] = 0;
}

static void fillFileFib(struct FileInfoBlock *fib, const char *name, ULONG size)
{
   fib->fib_DiskKey = 0;
   fib->fib_DirEntryType = -3;                    /* file */
   fib->fib_EntryType = -3;
   putBStr((UBYTE *)fib->fib_FileName, name, 106);
   fib->fib_Protection = 0;
   fib->fib_Size = (LONG)size;
   fib->fib_NumBlocks = (LONG)((size + 511) / 512);
   fib->fib_Comment[0] = 0;
}

static void doExamineObject(struct DosPacket *pkt)
{
   struct MyLock *lk = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg1);
   struct FileInfoBlock *fib = (struct FileInfoBlock *)BADDR((BPTR)pkt->dp_Arg2);

   if (lk && lk->isFile)
   {
      fillFileFib(fib, lk->name, lk->fsize);
   }
   else                                           /* a directory */
   {
      const char *nm = (lk && lk->name[0]) ? lk->name : "SHARED";
      fillDirFib(fib, nm, (lk && lk->dir[0]) ? 2 : 1);
      if (lk)
         lk->exNext = 0;                          /* reset directory scan */
      listDir(lk ? lk->dir : "");                 /* prime list for ExNext */
   }
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
}

static void doExamineNext(struct DosPacket *pkt)
{
   struct MyLock *lk = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg1);
   struct FileInfoBlock *fib = (struct FileInfoBlock *)BADDR((BPTR)pkt->dp_Arg2);
   LONG pos;

   if (!lk || lk->isFile || listDir(lk->dir) != 0)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_NO_MORE_ENTRIES;
      return;
   }

   pos = lk->exNext;
   while (pos < filecount &&
          !(files[pos].Type == BLUESCSI_FILE ||
            (gHaveDirs && files[pos].Type == BLUESCSI_DIR)))
      pos++;                                       /* skip unusable entries */

   if (pos >= filecount)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_NO_MORE_ENTRIES;
      return;
   }

   if (files[pos].Type == BLUESCSI_FILE)
      fillFileFib(fib, files[pos].Name, files[pos].Size);
   else
      fillDirFib(fib, files[pos].Name, 2);
   lk->exNext = pos + 1;
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
}

static void doFindInput(struct DosPacket *pkt)
{
   struct FileHandle *fh = (struct FileHandle *)BADDR((BPTR)pkt->dp_Arg1);
   struct MyLock *base = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg2);
   char dir[64];
   char leaf[40];
   LONG err, t, idx;
   ULONG size;
   struct MyFH *mfh;
   LONG r;

   if ((err = resolvePath(base, pkt->dp_Arg3, dir, leaf)) != 0)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = err;
      return;
   }
   if (leaf[0] == '\0')
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_OBJECT_WRONG_TYPE;
      return;
   }
   r = findEntry(dir, leaf, &t, &idx, &size);
   if (r <= 0)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = (r < 0) ? -r : ERROR_OBJECT_NOT_FOUND;
      return;
   }
   if (t != BLUESCSI_FILE)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_OBJECT_WRONG_TYPE;
      return;
   }

   mfh = AllocVec(sizeof(struct MyFH), MEMF_CLEAR | MEMF_PUBLIC);
   if (!mfh)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_NO_FREE_STORE;
      return;
   }
   mfh->index = idx;
   mfh->fsize = size;
   mfh->pos = 0;
   cCopy(mfh->dir, dir, sizeof(mfh->dir));
   fh->fh_Arg1 = (LONG)mfh;
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
}

static void doRead(struct DosPacket *pkt)
{
   struct MyFH *mfh = (struct MyFH *)pkt->dp_Arg1;
   UBYTE *buf = (UBYTE *)pkt->dp_Arg2;
   ULONG len = (ULONG)pkt->dp_Arg3;
   LONG got;

   if (!mfh)
   {
      pkt->dp_Res1 = -1;
      pkt->dp_Res2 = ERROR_INVALID_LOCK;
      return;
   }
   if (mfh->pos >= mfh->fsize || len == 0)
   {
      pkt->dp_Res1 = 0;                            /* EOF */
      return;
   }
   if (len > mfh->fsize - mfh->pos)
      len = mfh->fsize - mfh->pos;

   if (navTo(mfh->dir) != 0)                       /* GET_FILE indexes are per-dir */
   {
      pkt->dp_Res1 = -1;
      pkt->dp_Res2 = ERROR_DIR_NOT_FOUND;
      return;
   }
   got = Toolbox_Get_Bytes((int)mfh->index, mfh->pos, buf, len);
   if (got < 0)
   {
      pkt->dp_Res1 = -1;
      pkt->dp_Res2 = ERROR_SEEK_ERROR;
      return;
   }
   mfh->pos += (ULONG)got;
   pkt->dp_Res1 = got;
   pkt->dp_Res2 = 0;
}

static void doSeek(struct DosPacket *pkt)
{
   struct MyFH *mfh = (struct MyFH *)pkt->dp_Arg1;
   LONG offset = pkt->dp_Arg2;
   LONG mode = pkt->dp_Arg3;
   LONG oldpos;
   LONG newpos;

   if (!mfh || mfh->isWrite)            /* upload is sequential; no seek */
   {
      pkt->dp_Res1 = -1;
      pkt->dp_Res2 = ERROR_SEEK_ERROR;
      return;
   }
   oldpos = (LONG)mfh->pos;

   if (mode == OFFSET_BEGINNING)
      newpos = offset;
   else if (mode == OFFSET_END)
      newpos = (LONG)mfh->fsize + offset;
   else                                            /* OFFSET_CURRENT */
      newpos = oldpos + offset;

   if (newpos < 0 || newpos > (LONG)mfh->fsize)
   {
      pkt->dp_Res1 = -1;
      pkt->dp_Res2 = ERROR_SEEK_ERROR;
      return;
   }
   mfh->pos = (ULONG)newpos;
   pkt->dp_Res1 = oldpos;
   pkt->dp_Res2 = 0;
}

static void doEnd(struct DosPacket *pkt)
{
   struct MyFH *mfh = (struct MyFH *)pkt->dp_Arg1;
   if (mfh)
   {
      if (mfh->isWrite)                            /* finish the upload */
      {
         if (mfh->wbuflen > 0)
            Toolbox_Send_Block(mfh->wblock, mfh->wbuf, (int)mfh->wbuflen);
         Toolbox_Send_End();
         gListedValid = 0;                         /* new file appears now */
      }
      FreeVec(mfh);
   }
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
}

static void doFindOutput(struct DosPacket *pkt)
{
   struct FileHandle *fh = (struct FileHandle *)BADDR((BPTR)pkt->dp_Arg1);
   struct MyLock *base = (struct MyLock *)BADDR((BPTR)pkt->dp_Arg2);
   char dir[64];
   char leaf[40];
   LONG err, t, idx;
   ULONG size;
   struct MyFH *mfh;
   LONG r;

   if ((err = resolvePath(base, pkt->dp_Arg3, dir, leaf)) != 0)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = err;
      return;
   }
   if (leaf[0] == '\0')                            /* can't create the root */
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_OBJECT_WRONG_TYPE;
      return;
   }
   r = findEntry(dir, leaf, &t, &idx, &size);      /* also navigates to 'dir' */
   if (r < 0)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = -r;
      return;
   }
   if (r == 1 && t != BLUESCSI_FILE)               /* name taken by a subdir */
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_OBJECT_WRONG_TYPE;
      return;
   }

   if (Toolbox_Send_Prep(leaf) != 0)              /* opens/creates on the SD card */
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_OBJECT_IN_USE;
      return;
   }
   gListedValid = 0;                               /* dir listing now stale */

   mfh = AllocVec(sizeof(struct MyFH), MEMF_CLEAR | MEMF_PUBLIC);
   if (!mfh)
   {
      Toolbox_Send_End();                          /* close the prepared file */
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_NO_FREE_STORE;
      return;
   }
   mfh->isWrite = 1;
   cCopy(mfh->dir, dir, sizeof(mfh->dir));
   fh->fh_Arg1 = (LONG)mfh;
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
}

static void doWrite(struct DosPacket *pkt)
{
   struct MyFH *mfh = (struct MyFH *)pkt->dp_Arg1;
   UBYTE *src = (UBYTE *)pkt->dp_Arg2;
   ULONG len = (ULONG)pkt->dp_Arg3;
   ULONG done = 0;

   if (!mfh || !mfh->isWrite)
   {
      pkt->dp_Res1 = -1;
      pkt->dp_Res2 = ERROR_INVALID_LOCK;
      return;
   }

   while (done < len)                              /* fill 512-byte blocks, flush each */
   {
      ULONG space = 512 - mfh->wbuflen;
      ULONG n = len - done;
      if (n > space)
         n = space;
      CopyMem(src + done, mfh->wbuf + mfh->wbuflen, n);
      mfh->wbuflen += n;
      done += n;
      if (mfh->wbuflen == 512)
      {
         if (Toolbox_Send_Block(mfh->wblock, mfh->wbuf, 512) != 0)
         {
            pkt->dp_Res1 = -1;
            pkt->dp_Res2 = ERROR_DISK_FULL;
            return;
         }
         mfh->wblock++;
         mfh->wbuflen = 0;
      }
   }
   pkt->dp_Res1 = (LONG)len;
   pkt->dp_Res2 = 0;
}

static void doInfo(struct DosPacket *pkt, struct InfoData *id)
{
   id->id_NumSoftErrors = 0;
   id->id_UnitNumber = gUnit;
   id->id_DiskState = ID_VALIDATED;
   id->id_NumBlocks = 0x7FFFFFFF / 512;
   id->id_NumBlocksUsed = 0;
   id->id_BytesPerBlock = 512;
   id->id_DiskType = ID_SHARED_DISK;
   id->id_VolumeNode = gVolBptr;
   id->id_InUse = 0;
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
}

/* ---- entry / loop ------------------------------------------------------ */

LONG handlerMain(void)
{
   struct DosPacket *pkt;
   struct Message *msg;
   struct DeviceNode *dn;
   struct FileSysStartupMsg *fssm;
   char devname[64];
   int running = 1;

   SysBase = *(struct ExecBase **)4L;
   gProc = (struct Process *)FindTask(NULL);

   WaitPort(&gProc->pr_MsgPort);
   msg = GetMsg(&gProc->pr_MsgPort);
   pkt = (struct DosPacket *)msg->mn_Node.ln_Name;

   DOSBase = (struct DosLibrary *)OpenLibrary("dos.library", 37L);
   UtilityBase = OpenLibrary("utility.library", 37L);
   if (!DOSBase || !UtilityBase)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_INVALID_RESIDENT_LIBRARY;
      goto reply_and_exit;
   }

   dn = (struct DeviceNode *)BADDR((BPTR)pkt->dp_Arg3);
   fssm = (struct FileSysStartupMsg *)BADDR(dn->dn_Startup);
   gUnit = fssm->fssm_Unit;
   leafFromBStr(fssm->fssm_Device, devname, sizeof(devname));
   /* leafFromBStr would strip a ':' - device names have none, so this is just
      a plain BSTR->C copy here. */

   if (scsi_setup(devname, (int)gUnit) != 0)
   {
      pkt->dp_Res1 = DOSFALSE;
      pkt->dp_Res2 = ERROR_DEVICE_NOT_MOUNTED;
      goto reply_and_exit;
   }

   /* Subdirectory support (firmware v2026.04.27+): learn the device's default
      shared dir so relative paths can be composed below it. */
   if (scsi_capabilities & BLUESCSI_TOOLBOX_CAP_SET_WORKING_DIR)
   {
      if (Toolbox_Get_Working_Dir(gBaseDir, sizeof(gBaseDir)) == 0 && gBaseDir[0])
      {
         gHaveDirs = 1;
         cCopy(gCurAbs, gBaseDir, sizeof(gCurAbs));
      }
   }

   /* Create a DLT_VOLUME node so Workbench shows SHARED: as a disk and locks
      have a real volume to point at. Falls back to the device node if it fails. */
   gVol = MakeDosEntry("SHARED", DLT_VOLUME);
   if (gVol)
   {
      gVol->dol_Task = &gProc->pr_MsgPort;
      DateStamp(&gVol->dol_misc.dol_volume.dol_VolumeDate);
      gVol->dol_misc.dol_volume.dol_DiskType = ID_SHARED_DISK;
      AddDosEntry(gVol);
      gVolBptr = MKBADDR(gVol);
   }
   else
   {
      gVolBptr = (BPTR)pkt->dp_Arg3;
   }

   dn->dn_Task = &gProc->pr_MsgPort;
   pkt->dp_Res1 = DOSTRUE;
   pkt->dp_Res2 = 0;
   {
      struct MsgPort *rp = pkt->dp_Port;
      pkt->dp_Port = &gProc->pr_MsgPort;
      msg->mn_Node.ln_Name = (char *)pkt;
      PutMsg(rp, msg);
   }

   while (running)
   {
      WaitPort(&gProc->pr_MsgPort);
      while ((msg = GetMsg(&gProc->pr_MsgPort)) != NULL)
      {
         struct MsgPort *rp;
         pkt = (struct DosPacket *)msg->mn_Node.ln_Name;
         pkt->dp_Res1 = DOSFALSE;
         pkt->dp_Res2 = 0;

         switch (pkt->dp_Type)
         {
         case ACTION_IS_FILESYSTEM:  pkt->dp_Res1 = DOSTRUE; break;
         case ACTION_CURRENT_VOLUME: pkt->dp_Res1 = (LONG)gVolBptr; break;
         case ACTION_LOCATE_OBJECT:  doLocateObject(pkt); break;
         case ACTION_FREE_LOCK:      freeLock((BPTR)pkt->dp_Arg1); pkt->dp_Res1 = DOSTRUE; break;
         case ACTION_COPY_DIR:       doCopyDir(pkt); break;
         case ACTION_PARENT:         doParent(pkt); break;
         case ACTION_EXAMINE_OBJECT: doExamineObject(pkt); break;
         case ACTION_EXAMINE_NEXT:   doExamineNext(pkt); break;
         case ACTION_FINDINPUT:      doFindInput(pkt); break;
         case ACTION_FINDOUTPUT:     doFindOutput(pkt); break;
         case ACTION_READ:           doRead(pkt); break;
         case ACTION_WRITE:          doWrite(pkt); break;
         case ACTION_SEEK:           doSeek(pkt); break;
         case ACTION_END:            doEnd(pkt); break;
         case ACTION_INFO:           doInfo(pkt, (struct InfoData *)BADDR((BPTR)pkt->dp_Arg2)); break;
         case ACTION_DISK_INFO:      doInfo(pkt, (struct InfoData *)BADDR((BPTR)pkt->dp_Arg1)); break;

         case ACTION_DIE:
            pkt->dp_Res1 = DOSTRUE;
            running = 0;
            break;

         /* Firmware has no delete/rename/mkdir ops -> fail gracefully. */
         case ACTION_DELETE_OBJECT:
            pkt->dp_Res2 = ERROR_DELETE_PROTECTED;
            break;
         case ACTION_RENAME_OBJECT:
         case ACTION_CREATE_DIR:
            pkt->dp_Res2 = ERROR_WRITE_PROTECTED;
            break;

         /* No protection/comment/date storage either, but Copy clones these
            after writing and treats a failure as the whole copy failing
            ("file is write protected", verified on hardware 2026-08-06) -
            so accept and discard them like other metadata-less filesystems. */
         case ACTION_SET_PROTECT:
         case ACTION_SET_COMMENT:
         case ACTION_SET_DATE:
            pkt->dp_Res1 = DOSTRUE;
            break;

         default:
            pkt->dp_Res1 = DOSFALSE;
            pkt->dp_Res2 = ERROR_ACTION_NOT_KNOWN;
            break;
         }

         rp = pkt->dp_Port;
         pkt->dp_Port = &gProc->pr_MsgPort;
         msg->mn_Node.ln_Name = (char *)pkt;
         PutMsg(rp, msg);
      }
   }

   if (gVol)                            /* remove the volume node on unmount */
   {
      LockDosList(LDF_VOLUMES | LDF_WRITE);
      RemDosEntry(gVol);
      UnLockDosList(LDF_VOLUMES | LDF_WRITE);
      FreeDosEntry(gVol);
      gVol = NULL;
   }
   if (gHaveDirs)
      Toolbox_Set_Working_Dir("");     /* leave the device at its default dir */
   scsi_cleanup();

reply_and_exit:
   if (running == 0)
   {
      /* normal ACTION_DIE path already replied each packet */
   }
   else
   {
      /* startup failure: reply the startup packet we still hold */
      struct MsgPort *rp = pkt->dp_Port;
      pkt->dp_Port = &gProc->pr_MsgPort;
      msg->mn_Node.ln_Name = (char *)pkt;
      PutMsg(rp, msg);
   }
   if (UtilityBase)
      CloseLibrary(UtilityBase);
   if (DOSBase)
      CloseLibrary((struct Library *)DOSBase);
   return 0;
}

/* scsi.c calls MessageBox on errors (normally common.c -> Intuition). The
 * handler has no UI, so swallow it and avoid pulling in Intuition. */
void MessageBox(char *title, char *body)
{
   (void)title;
   (void)body;
}

antxiko-frogger-disassembly-makefile.text:
# Frogger (Konami, MSX1) - desensamblado
#
# El orden de las cosas: trazar el flujo -> generar el listado -> comprobar que
# vuelve a dar la ROM byte a byte -> las comprobaciones que el reensamblado NO
# cubre.
#
# La ROM no se distribuye. Hace falta en la raiz como frogger.rom, y
# `make comprueba` verifica el sha256.

ROM      = frogger.rom
SHA      = 0d60ff78e1ab466bce6e888193ca62d6df71fa07344c8ea31f7a8b486323c5f5
SRC      = src
WORK     = work
ORG      = 0x4000
TITULO   = FROGGER - Konami - MSX1 - cartucho RC-704 de 8 KB en la pagina 1

OMSX     = $(WORK)/omsx

all: listado verify sanity test

$(ROM):
	@echo "=================================================================="
	@echo " Falta $(ROM), y este repositorio NO lo distribuye."
	@echo ""
	@echo " Es Frogger (Konami, RC-704) para MSX, 8192 bytes exactos."
	@echo " Ponlo aqui con ese nombre. Para comprobar que es el mismo:"
	@echo "     shasum -a 256 $(ROM)"
	@echo "     $(SHA)"
	@echo ""
	@echo " Sin el se puede leer el listado ya generado en $(SRC)/, y los"
	@echo " tests que no dependen del binario siguen pasando."
	@echo "=================================================================="
	@false

comprueba: $(ROM)
	@echo "$(SHA)  $(ROM)" | shasum -a 256 -c -

# El trazado sigue el flujo desde los puntos de entrada. Los que no se pueden
# deducir estaticamente -ganchos de interrupcion, destinos de saltos
# indirectos- estan declarados en el .entries, cada uno con su justificacion.
$(WORK)/frogger.trace.json: $(ROM) $(SRC)/frogger.entries $(SRC)/frogger.nocode
	@mkdir -p $(WORK)
	python3 tools/z80trace.py $(ROM) $(ORG) $(SRC)/frogger.entries \
	        $(WORK)/frogger $(SRC)/frogger.nocode

trace: $(WORK)/frogger.trace.json

listado: $(WORK)/frogger.trace.json $(SRC)/frogger.notes
	python3 tools/mkasm.py $(ROM) $(ORG) $(WORK)/frogger.trace.json \
	        $(SRC)/frogger.notes work/msx.sym $(SRC)/frogger.asm "$(TITULO)"

# La prueba que decide si el desensamblado es fiable.
verify: $(SRC)/frogger.asm $(ROM)
	@sh tools/verify_build.sh $(SRC)/frogger.asm $(ROM) $(ORG)

# Lo que el reensamblado NO puede cazar: que unos datos se esten leyendo como
# codigo. El binario sale identico igual, porque los bytes no cambian; lo unico
# que cambia es lo que decimos de ellos.
sanity: $(WORK)/frogger.trace.json
	@echo "=================================================================="
	@echo " ningun byte declarado como datos puede salir como codigo"
	@echo "=================================================================="
	@python3 tools/check_trace.py $(WORK)/frogger.trace.json $(SRC)/frogger.nocode
	@python3 tools/check_datos_como_codigo.py $(WORK) $(SRC)
	@echo "=================================================================="
	@echo " ningun punto de entrada puede caer dentro de una zona de datos"
	@echo "=================================================================="
	@python3 tools/check_entradas.py $(SRC)/frogger.entries $(SRC)/frogger.notes \
	        $(SRC)/frogger.nocode
	@echo "=================================================================="
	@echo " ni un byte del cartucho sin asignar"
	@echo "=================================================================="
	@python3 tools/presupuesto.py $(WORK) $(SRC)

test:
	@echo "=================================================================="
	@echo " Tests"
	@echo "=================================================================="
	@python3 -m unittest discover -s tests -v

clean:
	rm -rf $(WORK)/frogger.trace.json $(WORK)/frogger.map $(WORK)/png


PYMUS ?= python3     # el que tenga numpy y lameenc
# La musica: el motor del cartucho ejecutado (tools/musica.py) a MP3
musica: $(ROM)
	$(PYMUS) tools/musica.py todas docs/audio
	$(PYMUS) tools/pagina_musica.py

.PHONY: musica all comprueba trace listado verify sanity test clean imagenes web

# ---------------------------------------------------------------------------
# Las imagenes y la web
# ---------------------------------------------------------------------------
# No hacen falta capturas de emulador: tools/graficos.py sube a una memoria de
# video de mentira lo mismo que sube el cartucho, con sus mismas direcciones, y
# monta la pantalla con sus mismas listas de rotulos.
imagenes: $(ROM)
	@mkdir -p docs/imagenes work/gfx
	python3 tools/graficos.py $(ROM) work/gfx
	@cp work/gfx/titulo.png work/gfx/rotulo.png docs/imagenes/
	@cp work/gfx/partida.png work/gfx/sprites.png docs/imagenes/
	@cp work/gfx/caracteres.png work/gfx/coches.png docs/imagenes/
	@cp work/gfx/trazado1.png work/gfx/trazado2.png docs/imagenes/
	@cp work/gfx/trazado4.png work/gfx/trazado5.png docs/imagenes/

web: imagenes
	python3 tools/md2html.py docs en
	python3 tools/md2html.py docs/es es
	python3 tools/make_web.py docs/imagenes docs/index.html en
	python3 tools/make_web.py docs/imagenes docs/es/index.html es
	@touch docs/.nojekyll
	@python3 tools/check_enlaces.py docs

bloodmosher-amigasparkler-src-sparkler-c.text:
// Amiga Sparkler Copyright 2021 by Bloodmosher
// Use this tool to verify RGB2HDMI boards built for the Amiga.
// The default settings at startup typically exhibit sparkling
// on boards that have issues.
// Any modifications to this code must include the above comment
// followed by documentation of the changes below.

#include <exec/types.h>
#include <exec/memory.h>
#include <exec/exec.h>
#include <intuition/intuition.h>
#include <hardware/cia.h>
#include <hardware/intbits.h>
#include <graphics/gfxbase.h>
#include <graphics/gfxmacros.h>
#include <graphics/copper.h>
#include <hardware/dmabits.h>
#include <devices/keyboard.h>

struct ExecLibrary* SysBase = NULL;
struct GfxBase* GfxBase = NULL;
struct DiskfontBase* DiskfontBase = NULL;

extern struct Custom custom;
extern struct CIA ciaa;

// Two copperlists, second used for interlaced mode
UWORD* g_pCopperList = NULL;
UWORD* g_pCopperList2 = NULL;

// Pointer to the main bitmap used for displaying test patterns
struct BitMap* g_pBitmap = NULL;

// RastPort used by Draw() to draw on bitmaps
struct RastPort g_rp;

// Any registers that need to be restored on exit can be saved here
struct Custom g_oldRegs;

// Keyboard related stuff
struct IOStdReq* KeyIO = NULL;
struct MsgPort* KeyMP;
char* keyMatrix;
#define MATRIX_SIZE 16L

void ReadKeyboard()
{
    KeyIO->io_Command = KBD_READMATRIX;
    KeyIO->io_Data = (APTR)keyMatrix;
    KeyIO->io_Length = MATRIX_SIZE;

    DoIO((struct IORequest*)KeyIO);
}

BOOL GetKeyState(int rawKey)
{
    if (keyMatrix == NULL)
        return FALSE;

    // raw key is the bit number
    int byteNumber = rawKey / 8;
    int bitNumber = rawKey % 8;

    if ((keyMatrix[byteNumber] & (1<<bitNumber))!=0)
        return TRUE;

    return FALSE;
}

// Allocate and initialize a bitmap with the specified line mode
void createBitmap(int width, int height, int lineMode)
{
    g_pBitmap = AllocBitMap(width, height, 4, BMF_CLEAR|BMF_DISPLAYABLE);

    g_rp.BitMap = g_pBitmap;
    struct RastPort* rp = &g_rp;

    int bytesPerLine = width/8; 

    BOOL evenX = FALSE;
    int xCounter = 0;
    for (int x=0; x < bytesPerLine; x++) 
    {
        BOOL evenLine = TRUE;
        for (int y=0; y < height; y++)
        {
            int index = (y * bytesPerLine);
            index += x;
            UBYTE val = 0x55;

            if (y == height - 1)
            {
                g_pBitmap->Planes[0][index] = 0xff;
            }
            else if (lineMode == 1) // alternating pixels
            {
                if (evenLine)
                {
                    g_pBitmap->Planes[0][index] = 0x55;
                } 
                else
                {
                    g_pBitmap->Planes[0][index] = 0xAA;
                }
            }
            else if (lineMode == 2) // vertical bars
            {
                if (evenX)
                {
                    g_pBitmap->Planes[0][index] = 0xAA;
                }
                else
                {
                    g_pBitmap->Planes[0][index] = 0xAA;
                }
            }
            else if (lineMode == 3) // horizontal bars
            {
                if (evenLine)
                {
                    g_pBitmap->Planes[0][index] = 0xFF;
                }
                else
                {
                    g_pBitmap->Planes[0][index] = 0x00;
                }
            }
            else if (lineMode == 4) // solid fill
            {
                g_pBitmap->Planes[0][index] = 0xff;
            }
            else if (lineMode == 5) // vertical bars 2
            {
                if (xCounter == 0)
                {
                    g_pBitmap->Planes[0][index] = 0x92;
                }
                else if (xCounter == 1)
                {
                    g_pBitmap->Planes[0][index] = 0x49;
                }
                else if (xCounter == 2)
                {
                    g_pBitmap->Planes[0][index] = 0x24;
                }

            }
            else if (lineMode == 6) // vertical bars 3
            {
                g_pBitmap->Planes[0][index] = 0x88;
            }
            else if (lineMode == 7) // vertical bars 3
            {
                if (xCounter == 0)
                {
                    g_pBitmap->Planes[0][index] = 0x84;
                }
                else if (xCounter == 1)
                {
                        g_pBitmap->Planes[0][index] = 0x21;
                }
                else if (xCounter == 2)
                {
                    g_pBitmap->Planes[0][index] = 0x8;
                }
                else if (xCounter == 3)
                {
                    g_pBitmap->Planes[0][index] = 0x42;
                }
                else if (xCounter == 4)
                {
                    g_pBitmap->Planes[0][index] = 0x10;
                }
            }

            evenLine = !evenLine;
        }
        evenX = !evenX;
        xCounter++;
        if (lineMode == 5 && xCounter == 3)
        {
            xCounter = 0;
        }
        if (lineMode == 7 && xCounter == 5)
        {
            xCounter = 0;
        }
    }
}

void freeBitmap()
{
    FreeBitMap(g_pBitmap);
}

struct 
{
    int copperList1ColorStartIndex;
    int copperList2ColorStartIndex;

    UWORD r[2];
    UWORD g[2];
    UWORD b[2];

} Globals;

struct DebugInfo
{
    int width;
    int height;
    BOOL interlaced;
    BOOL hires;
    int lineMode;
    BOOL colorOrTextChanged;
    BOOL showhelp;
    char debugText[255];
    BOOL pal;
    struct TextFont* pFont1;
};

// Create copperlists and start the display
void setupDisplay(BOOL hires, BOOL interlaced, BOOL pal)
{
    const int loresInterlacedBpl = 0x28;
    const int hiresInterlacedBpl = 0x50;

    if (pal)
    {
        custom.beamcon0 = 0x20;
    }
    else
    {
        custom.beamcon0 = 0x00;
    }

    custom.dmacon = DMAF_ALL;
    UWORD oldIntena = custom.intenar;
    custom.intena = 0x7fff; // disable interrupts

    UWORD bplmod = 0;
    if (interlaced)
    {
        if (hires)
        {
            bplmod = hiresInterlacedBpl;
        }
        else
        {
            bplmod = loresInterlacedBpl;
        }
    }

    int i = 0;
    g_pCopperList[i++] = 0x100; // bplcon0

    UWORD bplcon0 = 0x4200;
    if (hires)
    {
        bplcon0 = 0xC200;
    }
    if (interlaced)
    {
        bplcon0 |= 0x04;
    }
    g_pCopperList[i++] = bplcon0;

    g_pCopperList[i++] = 0x108; // bpl1mod
    g_pCopperList[i++] = bplmod;

    g_pCopperList[i++] = 0x10A; // bpl2mod
    g_pCopperList[i++] = bplmod;

    g_pCopperList[i++] = 0x092; // DDFSTART
    g_pCopperList[i++] = 0x38;

    g_pCopperList[i++] = 0x094; // DDFSTOP
    g_pCopperList[i++] = 0xd0;

    UWORD colorIndex = 0x180;

    // Setup a color palette; has more colors than we actually use
    UWORD colorValues[] = { 0, 0xfbf, 0x710, 0xC10, 0x910, 0xE20, 0xFCB, 0xFFF, 0xF42, 0x0, 0xF98, 0xF65, 0xC54, 0x322, 0x444, 0x888 };
    Globals.copperList1ColorStartIndex = i;

    for (int j=0;j < 16;j++)
    {
        g_pCopperList[i++] = colorIndex;
        colorIndex+=2;
        g_pCopperList[i++] = colorValues[j];
    }

    int bitplaneIndex = 0;
    g_pCopperList[i++] = 0x00E0;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF0000) >> 16;

    i++;
    g_pCopperList[i++] = 0x00E2;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF);
    i++;

    bitplaneIndex++;
    g_pCopperList[i++] = 0x00E4;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF0000) >> 16;

    i++;
    g_pCopperList[i++] = 0x00E6;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF);
    i++;

    bitplaneIndex++;
    g_pCopperList[i++] = 0x00E8;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF0000) >> 16;

    i++;
    g_pCopperList[i++] = 0x00EA;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF);
    i++;

    bitplaneIndex++;
    g_pCopperList[i++] = 0x00EC;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF0000) >> 16;

    i++;
    g_pCopperList[i++] = 0x00EE;
    g_pCopperList[i] = ((unsigned int)(g_pBitmap->Planes[bitplaneIndex]) & 0xFFFF);
    i++;

    // move #$3481, $dff08e (DIWSTRT)
    g_pCopperList[i++] = 0x008e;
    // g_pCopperList[i++] = 0x3481;
    g_pCopperList[i++] = 0x2c81;

    //0090 FCC1 move #$FCC1,$DFF090 (DIWSTOP)
    g_pCopperList[i++] = 0x0090;

    if (pal)
        g_pCopperList[i++] = 0x2CC1;
    else
        g_pCopperList[i++] = 0xF4C1;

    // For interlaced mode we need another copperlist for the other field
    if (interlaced)
    {
        int j = 0;
        g_pCopperList2[j++] = 0x100; // bplcon0

        bplcon0 = 0x4200;
        if (hires)
        {
            bplcon0 = 0xC200;
        }
        if (interlaced)
        {
            bplcon0 |= 0x04;
        }
        g_pCopperList2[j++] = bplcon0;

        g_pCopperList2[j++] = 0x108; // bpl1mod
        g_pCopperList2[j++] = bplmod;

        g_pCopperList2[j++] = 0x10A; // bpl2mod
        g_pCopperList2[j++] = bplmod;

        g_pCopperList2[j++] = 0x092; // DDFSTART
        g_pCopperList2[j++] = 0x38;

        g_pCopperList2[j++] = 0x094; // DDFSTOP
        g_pCopperList2[j++] = 0xd0;

        Globals.copperList2ColorStartIndex = j;

        for (int k=0;k < 16;k++)
        {
            g_pCopperList2[j++] = colorIndex;
            colorIndex+=2;
            g_pCopperList2[j++] = colorValues[k];
        }

        bitplaneIndex = 0;
        g_pCopperList2[j++] = 0x00E0;

        unsigned int bitplaneOffset = bplmod; 

        unsigned int addr = g_pBitmap->Planes[bitplaneIndex];
        addr += bitplaneOffset; // start on the next line for this field

        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF0000) >> 16;

        j++;
        g_pCopperList2[j++] = 0x00E2;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF);
        j++;

        bitplaneIndex++;
        addr = g_pBitmap->Planes[bitplaneIndex];
        addr += bitplaneOffset; // start on the next line for this field

        g_pCopperList2[j++] = 0x00E4;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF0000) >> 16;
        j++;

        g_pCopperList2[j++] = 0x00E6;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF);
        j++;

        bitplaneIndex++;
        addr = g_pBitmap->Planes[bitplaneIndex];
        addr += bitplaneOffset; // start on the next line for this field

        g_pCopperList2[j++] = 0x00E8;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF0000) >> 16;
        j++;

        g_pCopperList2[j++] = 0x00EA;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF);
        j++;

        bitplaneIndex++;
        addr = g_pBitmap->Planes[bitplaneIndex];
        addr += bitplaneOffset; // start on the next line for this field

        g_pCopperList2[j++] = 0x00EC;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF0000) >> 16;
        j++;

        g_pCopperList2[j++] = 0x00EE;
        g_pCopperList2[j] = ((unsigned int)(addr) & 0xFFFF);
        j++;

        // move #$3481, $dff08e (DIWSTRT)
        g_pCopperList2[j++] = 0x008e;
        // g_pCopperList[i++] = 0x3481;
        g_pCopperList2[j++] = 0x2c81;

        //0090 FCC1 move #$FCC1,$DFF090 (DIWSTOP)
        g_pCopperList2[j++] = 0x0090;

        if (pal)
        {
            g_pCopperList2[j++] = 0x2CC1;
        }
        else
        {
            g_pCopperList2[j++] = 0xF4C1;
        }

        // F401 FFFE wait HP=0(0x00),VP=244(0xF4) (VE=127,HE=127,BlitterFinishDisable=1)
        g_pCopperList2[j++] = 0xf401;
        g_pCopperList2[j++] = 0xfffe;

        // 0084 0002 move #$0002,$DFF084 (COP1LCH)
        g_pCopperList2[j++] = 0x080;
        g_pCopperList2[j++] = (UWORD)(((unsigned int)g_pCopperList & 0xFFFF0000) >> 16);

        // 0086 1050 move #$1050,$DFF086 (COP1LCL)
        g_pCopperList2[j++] = 0x082;
        g_pCopperList2[j++] = (UWORD)((unsigned int)g_pCopperList & 0xFFFF);

        //FFFF FFFE wait HP=254(0xFE),VP=255(0xFF) (VE=127,HE=127,BlitterFinishDisable=1)
        g_pCopperList2[j++] = 0xFFFF;
        g_pCopperList2[j++] = 0xFFFE;

        // the part that applies to the first copperlist
        // F401 FFFE wait HP=0(0x00),VP=244(0xF4) (VE=127,HE=127,BlitterFinishDisable=1)
        g_pCopperList[i++] = 0xf401;
        g_pCopperList[i++] = 0xfffe;

        // 0084 0002 move #$0002,$DFF084 (COP1LCH)
        g_pCopperList[i++] = 0x080;
        g_pCopperList[i++] = (UWORD)(((unsigned int)g_pCopperList2 & 0xFFFF0000) >> 16);

        // 0086 1050 move #$1050,$DFF086 (COP1LCL)
        g_pCopperList[i++] = 0x082;
        g_pCopperList[i++] = (UWORD)((unsigned int)g_pCopperList2 & 0xFFFF);
    }

    // copper list end
    g_pCopperList[i++] = 0xFFFF;
    g_pCopperList[i++] = 0xFFFE;


    int offset = 1; // color00, (write to value)
    // fix the colors to match what the user has set
    g_pCopperList[Globals.copperList1ColorStartIndex + offset] = (UWORD)((Globals.r[0] << 8) | (Globals.g[0] << 4) | Globals.b[0]);
    g_pCopperList2[Globals.copperList2ColorStartIndex + offset] = (UWORD)((Globals.r[0] << 8) | (Globals.g[0] << 4) | Globals.b[0]);

    offset = 3; // color00, value, color1 (2 bytes each), and now write to value (3 because this is a UWORD*)
    // fix the colors to match what the user has set
    g_pCopperList[Globals.copperList1ColorStartIndex + offset] = (UWORD)((Globals.r[1] << 8) | (Globals.g[1] << 4) | Globals.b[1]);
    g_pCopperList2[Globals.copperList2ColorStartIndex + offset] = (UWORD)((Globals.r[1] << 8) | (Globals.g[1] << 4) | Globals.b[1]);

    custom.cop1lc = g_pCopperList;
    custom.copjmp1 = 0;

    // DMAF_BLITTER is required if you want to use various RastPort functions like Text and SetRast
    custom.dmacon = DMAF_SETCLR|DMAF_RASTER|DMAF_COPPER|DMAF_BLITTER;
    custom.intena = INTF_SETCLR|INTF_INTEN|INTF_VERTB | oldIntena;
}

void ChangeColorValue(UWORD* colorValue, BOOL* colorOrTextChanged)
{
    if (GetKeyState(0x60) || GetKeyState(0x61))  // shift
    { 
        if (*colorValue < 0x0f)
        {
            (*colorValue)++;
            *colorOrTextChanged = TRUE;
        }
    }
    else
    {
        if (*colorValue > 0)
        {
            (*colorValue)--;
            *colorOrTextChanged = TRUE;
        }
    }
}

// Simple delay that works reasonably well on all Amigas
void Delay()
{
    for (int i=0;i<5;i++)
    {
        WaitTOF();
    }
}

void DrawDebugInfo(struct RastPort* rp, struct DebugInfo* dbgInfo)
{
    SetAPen(rp, 255);
    SetBPen(rp, 0);
    rp->DrawMode = JAM2;
    rp->cp_x = dbgInfo->hires ? 20 : 0;

    rp->cp_y = 10;
    char title[] = "Sparkler V1.0 - RGB2HDMI Test Tool - by Bloodmosher";
    Text(rp, title, strlen(title));

    rp->cp_x = dbgInfo->hires ? 20 : 0;
    rp->cp_y = 22;

    sprintf(dbgInfo->debugText, "%s %dx%d I:%d P:%d C0(R:%x G:%x B:%x) C1(R:%x G:%x B:%x)", 
                dbgInfo->pal ? "PAL" : "NTSC", 
                dbgInfo->width, 
                dbgInfo->height, 
                dbgInfo->interlaced, 
                dbgInfo->lineMode, 
                Globals.r[0], Globals.g[0], Globals.b[0], 
                Globals.r[1], Globals.g[1], Globals.b[1]);

    Text(rp, dbgInfo->debugText, strlen(dbgInfo->debugText));

    if (dbgInfo->showhelp)
    {
         char* helpLines[] = {
            {"F1: Toggle lores/hires"},
            {"F2: Toggle interlaced"},
            {"F3, F4, F5: Color 0 RGB - hold SHIFT for reverse direction"},
            {"F8, F9, F10: Color 1 RGB - hold SHIFT for reverse direction"},
            {"Number keys 1-7: Change image pattern"},
            {"SPACE: Toggle NTSC/PAL"},
            {"ESC: Exit"},
            {"HELP: Toggle help visibility"},
        };

        int helpLineCount = 8;
        int startY = 35;
        int positionX = 20;
        int lineSpacing = 10;

        for (int i=0;i<helpLineCount;i++)
        {
            rp->cp_x = positionX;
            rp->cp_y = startY + (i * lineSpacing);
            Text(rp, helpLines[i], strlen(helpLines[i]));
        }
    }
}

int openstuff()
{
    if (!(GfxBase = OpenLibrary ("graphics.library", 0L))) 
    {
        printf("graphics open failed.\n");
        die();
    }

    DiskfontBase = OpenLibrary("diskfont.library", 0L);

    KeyIO = AllocMem(sizeof(struct IOStdReq), MEMF_CLEAR);

    if (!OpenDevice("keyboard.device", 0, (struct IORequest*)KeyIO, 0))
    {
        if (KeyIO != NULL)
        {
            keyMatrix = AllocMem(MATRIX_SIZE, MEMF_CHIP|MEMF_CLEAR);
            KeyIO->io_Command = KBD_READMATRIX;
            KeyIO->io_Data = (APTR)keyMatrix;
            KeyIO->io_Length = MATRIX_SIZE;
        }
    }

    return 1;
}

closestuff()
{
    if (GfxBase)
    {
        CloseLibrary (GfxBase);
    }

    if (DiskfontBase)
    {
        CloseLibrary(DiskfontBase);
    }

    if (keyMatrix != NULL)
    {
        CloseDevice((struct IORequest*)KeyIO);
        FreeMem(keyMatrix, MATRIX_SIZE);
    }

    if (KeyIO != NULL)
    {
        FreeMem(KeyIO, sizeof(struct IOStdReq));
        KeyIO = NULL;
    }
}

die()
{
    closestuff();
    exit(-1);
}

int main(void)
{
    SysBase = *((struct Library**)0x00000004);

    printf("Sparkler V1.0 by Bloodmosher\n");

    int copperListSize = 2000;
    g_pCopperList = (UWORD*)AllocMem(copperListSize, MEMF_CHIP|MEMF_CLEAR);
    g_pCopperList2 = (UWORD*)AllocMem(copperListSize, MEMF_CHIP|MEMF_CLEAR);

    openstuff();

    struct View* oldView = GfxBase->ActiView;
    LoadView(NULL);
    WaitTOF();
    WaitTOF();

    g_oldRegs.intena = custom.intenar;
    g_oldRegs.dmacon = custom.dmaconr;

    // Set the default colors, bitmap info, and pattern to values that tend to exhibit sparkling on boards that have the issue
    Globals.r[0] = 0x0;
    Globals.g[0] = 0x0;
    Globals.b[0] = 0x0;

    Globals.r[1] = 0xf;
    Globals.g[1] = 0xb;
    Globals.b[1] = 0xf;

    BOOL changeDisplay = TRUE;

    struct DebugInfo dbgInfo;
    dbgInfo.width = 640;
    dbgInfo.height = 200;
    dbgInfo.interlaced = FALSE;
    dbgInfo.hires = TRUE;
    dbgInfo.lineMode = 1;
    dbgInfo.colorOrTextChanged = FALSE;
    dbgInfo.showhelp = TRUE;
    dbgInfo.pal = FALSE;

    createBitmap(320, 200, 1);

    InitRastPort(&g_rp);

    SetAPen(&g_rp, 255L);
    SetBPen(&g_rp, 0L);
    SetDrMd(&g_rp, JAM2);

    struct TextAttr textattr1 = { "helvetica.font", 11, 0, NULL };

    dbgInfo.pFont1 = OpenDiskFont(&textattr1);

    if (dbgInfo.pFont1)
    {
        SetFont(&g_rp, dbgInfo.pFont1);
    }

    setupDisplay(FALSE, FALSE, FALSE);

    if (((struct ExecBase*)SysBase)->VBlankFrequency == 50)
    {
        dbgInfo.pal = TRUE;
    }
    else
    {
        dbgInfo.pal = FALSE;
    }

    int count = 0;

    while(TRUE) 
    {
        ReadKeyboard();

        if (GetKeyState(0x057)) // F8 "r"
        { 
            ChangeColorValue(&Globals.r[1], &dbgInfo.colorOrTextChanged);
        }

        if (GetKeyState(0x058)) // F9 "g"
        { 
            ChangeColorValue(&Globals.g[1], &dbgInfo.colorOrTextChanged);
        }

        if (GetKeyState(0x059)) // F10 "b"
        {
            ChangeColorValue(&Globals.b[1], &dbgInfo.colorOrTextChanged);
        }

        if (GetKeyState(0x052)) // F3 "r"
        { 
            ChangeColorValue(&Globals.r[0], &dbgInfo.colorOrTextChanged);
        }

        if (GetKeyState(0x053)) // F4 "g"
        { 
            ChangeColorValue(&Globals.g[0], &dbgInfo.colorOrTextChanged);
        }

        if (GetKeyState(0x054)) // F5 "b"
        { 
            ChangeColorValue(&Globals.b[0], &dbgInfo.colorOrTextChanged);
        }

        if (GetKeyState(0x050)) // F1
        { 
            dbgInfo.hires = !dbgInfo.hires;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x051)) // F2
        { 
            dbgInfo.interlaced = !dbgInfo.interlaced;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x01)) 
        {
            dbgInfo.lineMode = 1;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x02)) 
        {
            dbgInfo.lineMode = 2;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x03)) 
        {
            dbgInfo.lineMode = 3;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x04)) 
        {
            dbgInfo.lineMode = 4;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x05)) 
        {
            dbgInfo.lineMode = 5;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x06)) 
        {
            dbgInfo.lineMode = 6;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x07)) 
        {
            dbgInfo.lineMode = 7;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x40)) 
        {
            dbgInfo.pal = !dbgInfo.pal;
            changeDisplay = TRUE;
        }

        if (GetKeyState(0x5F)) 
        {
            dbgInfo.showhelp = !dbgInfo.showhelp;

            if (dbgInfo.showhelp)
            {
                dbgInfo.colorOrTextChanged = TRUE;
            }
            else
            {
                changeDisplay = TRUE;
            }
        }

        if (GetKeyState(0x45)) // ESC - exit
        { 
            break;
        }

        if (dbgInfo.colorOrTextChanged && !changeDisplay)
        {
            WaitTOF();
            int offset = 1; // color00, (write to value)

            g_pCopperList[Globals.copperList1ColorStartIndex + offset] = (UWORD)((Globals.r[0] << 8) | (Globals.g[0] << 4) | Globals.b[0]);
            g_pCopperList2[Globals.copperList2ColorStartIndex + offset] = (UWORD)((Globals.r[0] << 8) | (Globals.g[0] << 4) | Globals.b[0]);

            offset = 3; // color00, value, color1 (2 bytes each), and now write to value (3 because this is a UWORD*)

            g_pCopperList[Globals.copperList1ColorStartIndex + offset] = (UWORD)((Globals.r[1] << 8) | (Globals.g[1] << 4) | Globals.b[1]);
            g_pCopperList2[Globals.copperList2ColorStartIndex + offset] = (UWORD)((Globals.r[1] << 8) | (Globals.g[1] << 4) | Globals.b[1]);

            g_rp.BitMap = g_pBitmap;

            struct RastPort* rp = &g_rp;
            DrawDebugInfo(rp, &dbgInfo);

            dbgInfo.colorOrTextChanged = FALSE;
            Delay();
        }

        if (changeDisplay)
        {
            WaitTOF();
            freeBitmap();
            if (dbgInfo.hires)
            {
                dbgInfo.width = 640;
            }
            else
            {
                dbgInfo.width = 320;
            }

            if (dbgInfo.interlaced)
            {
                if (dbgInfo.pal)
                    dbgInfo.height = 512;
                else
                    dbgInfo.height = 400;
            }
            else
            {
                if (dbgInfo.pal)
                    dbgInfo.height = 256;
                else
                    dbgInfo.height = 200;
            }

            createBitmap(dbgInfo.width, dbgInfo.height, dbgInfo.lineMode);
            setupDisplay(dbgInfo.hires, dbgInfo.interlaced, dbgInfo.pal);
            changeDisplay = FALSE;

            g_rp.BitMap = g_pBitmap;
            struct RastPort* rp = &g_rp;
            DrawDebugInfo(rp, &dbgInfo);
            Delay();
        }

        // exit it on mouse click
        if ((ciaa.ciapra & CIAF_GAMEPORT0) == 0)
        {
            break;
        }
    }

    // Returning to the system seems happier if not in int erlaced mode
    setupDisplay(FALSE, FALSE, FALSE);

    LoadView(oldView);
    WaitTOF();
    WaitTOF();

    custom.cop1lc = GfxBase->copinit;
    custom.dmacon = g_oldRegs.dmacon | 0x8000;
    custom.intena = g_oldRegs.intena | 0x8000;

    freeBitmap();

    if (dbgInfo.pFont1)
    {
        CloseFont(dbgInfo.pFont1);
    }

    FreeMem(g_pCopperList, copperListSize);
    FreeMem(g_pCopperList2, copperListSize);

    RethinkDisplay();
    closestuff();

    printf("\n");
    return 0;
}

antxiko-dunkshot-disassembly-makefile.text:
# Dunk Shot (HAL Laboratory, MSX1) - desensamblado
#
# El orden de las cosas: trazar el flujo -> generar el listado -> comprobar que
# vuelve a dar la ROM byte a byte -> las comprobaciones que el reensamblado NO
# cubre.
#
# El cartucho no se distribuye: hace falta en la raiz como dunkshot.rom, y
# `make comprueba` verifica su sha256.

ROM      = dunkshot.rom
SHA      = a1891e038566596a9f67067b8ea4694709aa9fee93c8ac0379360b30ea3abe62
SRC      = src
WORK     = work
ORG      = 0x4000
TITULO   = DUNK SHOT - HAL Laboratory - MSX1 - cartucho de 32 KB en las paginas 1 y 2

all: listado verify sanity test

$(ROM):
	@echo "=================================================================="
	@echo " Falta $(ROM), y este repositorio NO lo distribuye."
	@echo ""
	@echo " Es Dunk Shot (HAL Laboratory, 1986) para MSX, 32768 bytes exactos."
	@echo " Ponlo aqui con ese nombre. Para comprobar que es el mismo:"
	@echo "     shasum -a 256 $(ROM)"
	@echo "     $(SHA)"
	@echo "=================================================================="
	@false

comprueba: $(ROM)
	@echo "$(SHA)  $(ROM)" | shasum -a 256 -c -

# El trazado sigue el flujo desde los puntos de entrada. Los que no se pueden
# deducir estaticamente -ganchos de interrupcion, destinos de saltos
# indirectos- estan declarados en el .entries, cada uno con su justificacion.
$(WORK)/dunkshot.trace.json: $(ROM) $(SRC)/dunkshot.entries $(SRC)/dunkshot.nocode
	@mkdir -p $(WORK)
	python3 tools/z80trace.py $(ROM) $(ORG) $(SRC)/dunkshot.entries \
	        $(WORK)/dunkshot $(SRC)/dunkshot.nocode

trace: $(WORK)/dunkshot.trace.json

listado: $(WORK)/dunkshot.trace.json $(SRC)/dunkshot.notes
	python3 tools/mkasm.py $(ROM) $(ORG) $(WORK)/dunkshot.trace.json \
	        $(SRC)/dunkshot.notes work/msx.sym $(SRC)/dunkshot.asm "$(TITULO)"

# La prueba que decide si el desensamblado es fiable.
verify: $(SRC)/dunkshot.asm $(ROM)
	@sh tools/verify_build.sh $(SRC)/dunkshot.asm $(ROM) $(ORG)

# Lo que el reensamblado NO puede cazar: que unos datos se esten leyendo como
# codigo. El binario sale identico igual, porque los bytes no cambian; lo unico
# que cambia es lo que decimos de ellos.
sanity: $(WORK)/dunkshot.trace.json
	@echo "=================================================================="
	@echo " ningun byte declarado como datos puede salir como codigo"
	@echo "=================================================================="
	@python3 tools/check_trace.py $(WORK)/dunkshot.trace.json $(SRC)/dunkshot.nocode
	@python3 tools/check_datos_como_codigo.py $(WORK) $(SRC)
	@echo "=================================================================="
	@echo " ningun punto de entrada puede caer dentro de una zona de datos"
	@echo "=================================================================="
	@python3 tools/check_entradas.py $(SRC)/dunkshot.entries $(SRC)/dunkshot.notes \
	        $(SRC)/dunkshot.nocode
	@echo "=================================================================="
	@echo " ni un byte del cartucho sin asignar"
	@echo "=================================================================="
	@python3 tools/presupuesto.py $(WORK) $(SRC)

densidad:
	@python3 tools/densidad.py $(SRC)/dunkshot.asm

test:
	@echo "=================================================================="
	@echo " Tests"
	@echo "=================================================================="
	@python3 -m unittest discover -s tests -v

# LAS IMAGENES, montadas desde la ROM con tools/pantallas.py: ni una captura.
imagenes: $(ROM)
	python3 tools/imagenes.py $(ROM) docs/imagenes

# Y la prueba de que son las de verdad: cada pantalla contra un volcado de
# VRAM de openMSX, byte a byte (los volcados, en work/: ver coteja_todo.py).
coteja: $(ROM)
	@python3 tools/coteja_todo.py $(ROM)

# LA WEB. Bilingue: el ingles en docs/ y el castellano en docs/es/.
web: imagenes
	python3 tools/md2html.py docs en
	python3 tools/md2html.py docs/es es
	python3 tools/make_web.py docs/imagenes docs/index.html en
	python3 tools/make_web.py docs/imagenes docs/es/index.html es
	python3 tools/check_enlaces.py docs

# EL PARCHE MSX2: sprites en modo 2 (ocho por linea) en un MSX2, el mismo
# fichero sigue valiendo en un MSX1. Necesita pasmo en el PATH (o PASMO=...).
parche: $(ROM)
	python3 tools/parche_msx2.py $(ROM) $(WORK)/dunkshot_msx2.rom parche/dunkshot_msx2.ips parche/parche_msx2.asm

clean:
	rm -rf $(WORK)/dunkshot.trace.json $(WORK)/dunkshot.blocks

.PHONY: all comprueba trace listado verify sanity test densidad imagenes coteja web parche clean

