#!/usr/bin/python

import sys,os,png

class Colors:
	black,magenta,green,orange,blue = range(5)



def main(argv):

	if len(argv)<1:
		printHorzontalLookup()
		exit(0)

	pngfile = sys.argv[1]

	reader = png.Reader(pngfile)
	try:
		pngdata = reader.asRGB8()
	except:
		usage()

	disclaimer()

	width = pngdata[0]
	height = pngdata[1]
	pixeldata = pngdata[2]	
	byteWidth = width/2+1+1	 # TODO: Calculate a power of two for this

	for shift in range(0,7):
		print "%s_SHIFT%d: ;%d bytes per row" % (os.path.splitext(pngfile)[0].upper(),shift,byteWidth)

		spriteChunks = layoutSpriteChunk(pixeldata,width,height,shift)

		for row in range(height):
			for chunkIndex in range(len(spriteChunks)):
				print spriteChunks[chunkIndex][row]

		print "\n"				




def layoutSpriteChunk(pixeldata,width,height,shift):

	bitmap = [[0 for x in range(width)] for y in range(height)]

	byteWidth = width/2+1+1	 # TODO: Calculate a power of two for this
	spriteChunks = [["" for y in range(height)] for x in range(byteWidth)]

	for row in range(height):
		pixelRow = bitmap[row]
		bitStream = ""

		for pixelIndex in range(width):
			pixel = pixelColor(pixeldata,row,pixelIndex)
			if pixel == Colors.black:
				bitStream += "00"
			else:
				if pixel == Colors.green or pixel == Colors.orange:
					bitStream += "01"
				else:
					bitStream += "10"

		bitStream = shiftStringRight(bitStream,shift)
		bitStream = bitStream[:byteWidth*8]

		bitPos = 0
		byteSplits = [0 for x in range(byteWidth)]

		for byteIndex in range(byteWidth):
			remainingBits = len(bitStream) - bitPos

			bitChunk = ""

			if remainingBits < 0:
				bitChunk = "0000000"
			else:	
				if remainingBits < 7:
					bitChunk = bitStream[bitPos:]
					bitChunk += fillOutByte(7-remainingBits)
				else:	
					bitChunk = bitStream[bitPos:bitPos+7]				

			bitChunk = bitChunk[::-1]

			highBit = "0"
			if pixel == Colors.orange or pixel == Colors.blue:
				highBit = "1"

			byteSplits[byteIndex] = highBit + bitChunk
			bitPos += 7

		for chunkIndex in range(len(byteSplits)):
			spriteChunks[chunkIndex][row] = ".byte %%%s" % byteSplits[chunkIndex]

	return spriteChunks



def fillOutByte(numBits):
	filler = ""
	for bit in range(numBits):
		filler += "0"

	return filler


def shiftStringRight(string,shift):
	if shift==0:
		return string

	shift *=2	
	result = ""

	for i in range(shift):
		result += "0"

	result += string
	return result


def pixelColor(pixeldata,row,col):
	r = pixeldata[row][col*3]
	g = pixeldata[row][col*3+1]
	b = pixeldata[row][col*3+2]
	color = Colors.black

	if r==255 and g==0 and b==255:
		color = Colors.magenta
	else:
		if r==0 and g==255 and b==0:
			color = Colors.green
		else:
			if r==0 and g==0 and b==255:
				color = Colors.blue
			else:
				if r==255 and g>0 and b==0:
					color = Colors.orange

	return color


def printHorzontalLookup():
	disclaimer()

	print "HGRROWBYTES:"
	for byte in range(40):
		pixels = 4
		offset = 0
		if (byte%2):
			pixels = 3
			offset = -1

		for entry in range(pixels):
			print "\t.byte $%02x" % (byte + offset)

	print "\nHGRROWBYTES_BITSHIFT:"
	for pixel in range(140):
		print "\t.byte $%02x" % ((pixel % 7)*32) # 32 = 4 shifts of 8 bytes


def usage():
	print '''
Usage: HiSprite <png file>

PNG file must not have an alpha channel!
'''
	sys.exit(2)


def disclaimer():
	print '''
; This file was generated by SpriteGenerator.py, a sprite generation tool by Quinn Dunki.
; If you feel the need to modify this file, you are probably doing it wrong.
'''
	return

if __name__ == "__main__":
	main(sys.argv[1:])

jendo42-amigasplash-src-main-c.text:
/*

	amiga-splash, simple program for displaying boot splash screen

	Original code by:
		Wojciech Jeczmien (jeczmien@panda.bg.univ.gda.pl)
		Tak Tang          (tst92@ecs.soton.ac.uk)
		Michael Becker    (nf198@fim.uni-erlangen.de)

	Reworked by:
		Michal 'Jendo' Jenikovsky (jendo@jmsystems.sk)

*/

#include <stdbool.h>
#include <string.h>
#include <stdlib.h>

#include <exec/types.h>
#include <graphics/gfxbase.h>
#include <intuition/intuitionbase.h>
#include <intuition/intuition.h>
#include <intuition/screens.h>
#include <proto/intuition.h>
#include <proto/graphics.h>
#include <proto/iffparse.h>
#include <proto/exec.h>
#include <proto/dos.h>

#include "system.h"
#include "iff.h"
#include "player.h"
#include "log.h"
#include "wav.h"
#include "macros.h"

#define LOG(x) Write(Output(), x "\n", sizeof(x))

uint16_t __chip sprite_data[] = {
	0x0000, 0x0000,
	0x0000, 0x0000
};

struct ColorSpec colors_zero[33] = { 0 };


// NOTE: there is no need to call the intuition locks,
// because whole program is running in Disable()
// ULONG lock = LockIBase(0);
// ...
// UnlockIBase(lock);
uint16_t screenscnt()
{
	uint16_t cnt = 0;
	struct Screen * scr = IntuitionBase->FirstScreen;
	while (scr) {
		cnt++;
		scr = scr->NextScreen;
	}

	return cnt;
}

bool hasfocus(struct Screen *scr)
{
	bool result = IntuitionBase->FirstScreen == scr;
	return result;
}

void fade(struct Screen *scr, const uint16_t totalTicks, uint16_t *cmap, const uint16_t cmap_count, bool fadeOut)
{
	uint16_t tick = fadeOut ? totalTicks : 0;
	uint16_t temp[cmap_count];
	while (fadeOut ? tick-- : tick++ < totalTicks) {
		for (uint16_t i = 0, *p = &temp[0], *q = cmap; i < cmap_count; i++, p++, q++) {
			uint16_t col = *q;
			uint8_t r = (col >> 8) & 0x0F;
			uint8_t g = (col >> 4) & 0x0F;
			uint8_t b = (col >> 0) & 0x0F;
			r = tick * r / totalTicks;
			g = tick * g / totalTicks;
			b = tick * b / totalTicks;
			*p = (r << 8) | (g << 4) | (b << 0);
		}
		sys_vblank();
		LoadRGB4(&scr->ViewPort, temp, cmap_count);
	}
}

int main(int argc, char *argv[])
{
	struct Playback playback = {0};
	struct Window *mywin = NULL;
	struct Screen *scr = NULL;
	struct Screen *wbScreen = NULL;
	struct Screen *wbScreenLock = NULL;
	bool filterDisabled = false;
	const uint16_t cmap_zero[64] = { 0 };
	uint16_t cmap[64] = { 0 };

	(void)argc, (void)argv;

	LOG("amiga-splash " XSTR(GIT_VERSION));

	if (SysBase->LibNode.lib_Version < 36) {
		LOG("This program requires OS 2.0+");
		return ERROR_INVALID_RESIDENT_LIBRARY;
	}

	if (!sys_init()) {
		LOG("Failed to init the program, maybe not enough memory?");
		return ERROR_INVALID_RESIDENT_LIBRARY;
	}

	// If this program run, disable interrupts to minimize flicker
	Forbid();
	Disable();

	// send signal to existing AmigaSplash program to close it
	if (strstr(sys_commandline(), "signal")) {
		struct Task *targetTask = FindTask("AmigaSplash");
		if (targetTask) {
			Signal(targetTask, SIGBREAKF_CTRL_C);
		}

		Enable();
		Permit();
		sys_cleanup();
		return 0;
	}

	{ // rename self task
		struct Task *me = FindTask(NULL);
		me->tc_Node.ln_Name = "AmigaSplash";
	}

	// initialize empty color table
	colors_zero[32].ColorIndex = -1;
	for (uint16_t i = 0; i < 32; i++) {
		colors_zero[i].ColorIndex = i;
	}

	struct ImageInfo imageInfo = {0};
	if (!IFF_LoadImage("S:splash.iff", &imageInfo)) {
		LOG("No splash image.");
		goto end;
	}

	IFF_DeInterleave(&imageInfo);

	struct WavInfo wavInfo = {0};
	if (WAV_LoadFile("S:splash.wav", &wavInfo)) {
		filterDisabled = wavInfo.rate > 11025;
		LOG_DEBUG("Got sound at (%X,%X) of size %u; %u Hz", (uint32_t)wavInfo.left, (uint32_t)wavInfo.right, wavInfo.size, wavInfo.rate);
	} else {
		LOG("No sound file.");
	}

	struct Image image = {
		0,0,
		imageInfo.header.w,			/* Bitmap width - rounded up to multiples of 64 */
		imageInfo.header.h,			/* Bitmap height */
		imageInfo.header.nPlanes,	/* Image Depth : 8 bitplanes -> 256 colours */
		imageInfo.bitmap,
		0xff, 0x0,					/* PlanePick, PlaneOnOff */
		NULL
	};

	LOG_DEBUG("Got image at %X: %dx%d; %d planes", (uint32_t)image.ImageData, image.Width, image.Height, image.Depth);

	// convert the CMAP into OCS/ECS format
	UWORD cmap_size = imageInfo.cmsize / 3;
	if (cmap_size > 32) {
		cmap_size = 32;
	}
	for (UWORD i = 0; i < cmap_size; i++) {
		// Extract the 8-bit R, G, B values
		UBYTE red   = imageInfo.cmap[(i * 3) + 0];
		UBYTE green = imageInfo.cmap[(i * 3) + 1];
		UBYTE blue  = imageInfo.cmap[(i * 3) + 2];

		// Scale them down to 4-bit
		red   >>= 4;
		green >>= 4;
		blue  >>= 4;

		// Pack them into the Amiga 0x0RGB UWORD format
		cmap[i] = (red << 8) | (green << 4) | blue;
	}

	bool aga_present = sys_isaga();
	bool im_lace = image.Height > 256;
	bool im_ntsc = GfxBase->DisplayFlags & NTSC;

	uint32_t modeNormal = imageInfo.isham ? HAM_KEY : HIRES_KEY;
	uint32_t modeLaced = imageInfo.isham ? HAMLACE_KEY : HIRESLACE_KEY;
	uint32_t displayId = im_lace ? modeLaced : modeNormal;
	uint16_t type = CUSTOMSCREEN;
	if (imageInfo.isham) {
		type |= HAM;
	}

	int swh = imageInfo.isham ? 160 : 320;
	int shh = im_lace ? 256 : 128;
	if (im_ntsc) {
		shh -= (im_lace ? 56 : 28);
	}

	LOG_DEBUG("AGA: %s; LACED: %s; NTSC: %s; HAM: %s", YESNO(aga_present), YESNO(im_lace), YESNO(im_ntsc), YESNO(imageInfo.isham));
	LOG_DEBUG("Screen size: %ux%u", swh * 2, shh * 2);

	// create screen for splash, force all colors to black
	scr = OpenScreenTags(NULL,
		SA_Left, swh - (image.Width / 2),
		SA_Top, shh - (image.Height / 2),
		SA_Width, image.Width,
		SA_Height, image.Height,
		SA_Depth, image.Depth,
		SA_Title, (uint32_t)"SplashScreen",
		SA_Quiet, TRUE,
		SA_ShowTitle, FALSE,
		SA_Type, type,
		SA_DisplayID, displayId,
		SA_Draggable, FALSE,
		SA_Colors, (uint32_t)colors_zero,
		SA_Exclusive, TRUE,
		TAG_DONE
	);

	if (!scr) {
		LOG_DEBUG("Can't open screen");
		goto end;
	}

	// create workbench screen behind the splash screen
	wbScreen = OpenScreenTags(NULL,
		SA_Type, WBENCHSCREEN,
		SA_Title, (uint32_t)"Workbench",
		SA_PubName, (uint32_t)"Workbench",
		SA_Behind, TRUE,
		SA_LikeWorkbench, TRUE,
		TAG_DONE
	);

	// lock the wb screen to prevent changing order
	wbScreenLock = LockPubScreen(NULL);

	mywin = OpenWindowTags(NULL,
		WA_Left, 0,
		WA_Top, 0,
		WA_Width, image.Width,
		WA_Height, image.Height,
		WA_Flags, WFLG_SMART_REFRESH | WFLG_BORDERLESS | WFLG_RMBTRAP,
		WA_CustomScreen, (uint32_t)scr,
		WA_IDCMP, IDCMP_RAWKEY | IDCMP_CLOSEWINDOW | IDCMP_INACTIVEWINDOW | IDCMP_INTUITICKS | IDCMP_NEWPREFS | IDCMP_NEWSIZE,
		TAG_DONE
	);

	if (!mywin) {
		LOG_DEBUG("Can't open window");
		goto end;
	}

	if (imageInfo.isham) {
		// for HAM we need to just load the palette
		// fading will be turned off
		// NOTE: if you want border color black,
		// you need to make sure that the zeroth color
		// register is set to black color
		LoadRGB4(&scr->ViewPort, cmap, cmap_size);
	}

	SetPointer(mywin, sprite_data, 0, 0, 0, 0);
	DrawImage(mywin->RPort, &image, 0, 0);
	ActivateWindow(mywin);
	if (!imageInfo.isham) {
		fade(scr, 64, cmap, cmap_size, false);
	} else {
		Delay(64);
	}

	// program main loop
	uint16_t timer = 10;
	struct IntuiMessage *msg;
	uint32_t signalMask = (1UL << mywin->UserPort->mp_SigBit) | SIGBREAKF_CTRL_C;
	bool run = true;
	bool rexit = false;
	do {
		if (Wait(signalMask) & SIGBREAKF_CTRL_C) {
			LOG_DEBUG("Exit by: Signal");
			run = false;
			break;
		}
		while ((msg = (struct IntuiMessage *)GetMsg(mywin->UserPort))) {
			switch (msg->Class) {
				case IDCMP_RAWKEY:
					if (msg->Code == 0x45) {
						// ESC key press
						LOG_DEBUG("Exit by: ESC");
						rexit = true;
					}
					break;
				case IDCMP_NEWPREFS:
					LOG_DEBUG("Exit by: IDCMP_NEWPREFS");
					rexit = true;
					break;
				case IDCMP_NEWSIZE:
					LOG_DEBUG("Exit by: IDCMP_NEWSIZE");
					// redraw image to center
					//QueryOverscan(displayId, &rect, OSCAN_STANDARD);
					//ScreenPosition(scr, SPOS_ABSOLUTE, rect.MinX, rect.MinY, rect.MaxX, rect.MaxY);
					rexit = true;
					break;
				case IDCMP_CLOSEWINDOW:
					LOG_DEBUG("Exit by: IDCMP_CLOSEWINDOW");
					rexit = true;
					break;
				case IDCMP_INACTIVEWINDOW:
					LOG_DEBUG("Exit by: IDCMP_INACTIVEWINDOW");
					rexit = true;
					break;
				case IDCMP_INTUITICKS:
					if (timer) {
						--timer;
					}
					if (!hasfocus(scr)) {
						LOG_DEBUG("Exit by: screen change");
						rexit = true;
					}
					break;
			}
			ReplyMsg((struct Message *)msg);
		}

		if (!timer && rexit) {
			run = false;
		}

	} while (run);

	// start the jingle if available
	if (wavInfo.size) {
		if (filterDisabled) {
			sys_setfilter(false);
		}
		PL_StartStereoPCM(&playback, wavInfo.left, wavInfo.right ? wavInfo.right : wavInfo.left, wavInfo.size, wavInfo.rate);
	}

	// fade out
	if (!imageInfo.isham) {
		fade(scr, 64, cmap, cmap_size, true);
	} else {
		Delay(64);
	}

	// switch to WB screen and fade in
	if (wbScreen) {
		// save the original palette
		uint16_t cmap_wb[64] = { 0 };
		for (uint16_t i = wbScreen->ViewPort.ColorMap->Count, *src = (uint16_t *)wbScreen->ViewPort.ColorMap->ColorTable, *dst = cmap_wb; i; i--) {
			*dst++ = *src++;
		}

		// make it black
		LoadRGB4(&wbScreen->ViewPort, cmap_zero, wbScreen->ViewPort.ColorMap->Count);

		sys_vblank();
		ScreenToFront(wbScreen);
		fade(wbScreen, 64, cmap_wb, wbScreen->ViewPort.ColorMap->Count, false);
	}

end:
	// interrupts can be enabled now
	Enable();
	Permit();

	// cleanup
	IFF_FreeImage(&imageInfo);
	if (mywin) {
		CloseWindow(mywin);
	}
	if (scr) {
		CloseScreen(scr);
	}
	if (wbScreenLock){
		UnlockPubScreen(NULL, wbScreenLock);
	}
	if (wbScreen) {
		CloseScreen(wbScreen);
	}
	if (wavInfo.size) {
		LOG_DEBUG("Waiting for sound to end...");
		PL_WaitForPlayback(&playback);
		if (filterDisabled) {
			sys_setfilter(true);
		}

		PL_CleanupPlayback(&playback);
		WAV_Cleanup(&wavInfo);
	}
	sys_cleanup();
	return EXIT_SUCCESS;
}

antxiko-konamisgolf-disassembly-makefile.text:
# Konami's Golf (Konami, MSX1) - desensamblado
#
# El orden de las cosas: trazar el flujo -> generar el listado -> comprobar que
# vuelve a dar la ROM byte a byte -> las comprobaciones que el reensamblado NO
# cubre.
#
# La ROM no se distribuye. Hace falta en la raiz como golf.rom, y
# `make comprueba` verifica el sha256.

ROM      = golf.rom
SHA      = 6c539f0a4b46b3f723ded723a3bac036550e58385a6a9be73afb8ceb8c7ecae3
SRC      = src
WORK     = work
ORG      = 0x4000
TITULO   = KONAMI'S GOLF - Konami - MSX1 - cartucho RC-723 de 16 KB en la pagina 1

all: listado verify sanity test

$(ROM):
	@echo "=================================================================="
	@echo " Falta $(ROM), y este repositorio NO lo distribuye."
	@echo ""
	@echo " Es Konami's Golf (Konami, RC-723) para MSX, 16384 bytes exactos."
	@echo " Ponlo aqui con ese nombre. Para comprobar que es el mismo:"
	@echo "     shasum -a 256 $(ROM)"
	@echo "     $(SHA)"
	@echo "=================================================================="
	@false

comprueba: $(ROM)
	@echo "$(SHA)  $(ROM)" | shasum -a 256 -c -

# El trazado sigue el flujo desde los puntos de entrada. Los que no se pueden
# deducir estaticamente -ganchos de interrupcion, destinos de saltos
# indirectos- estan declarados en el .entries, cada uno con su justificacion.
$(WORK)/golf.trace.json: $(ROM) $(SRC)/golf.entries $(SRC)/golf.nocode
	@mkdir -p $(WORK)
	python3 tools/z80trace.py $(ROM) $(ORG) $(SRC)/golf.entries \
	        $(WORK)/golf $(SRC)/golf.nocode

trace: $(WORK)/golf.trace.json

listado: $(WORK)/golf.trace.json $(SRC)/golf.notes
	python3 tools/mkasm.py $(ROM) $(ORG) $(WORK)/golf.trace.json \
	        $(SRC)/golf.notes work/msx.sym $(SRC)/golf.asm "$(TITULO)"

# La prueba que decide si el desensamblado es fiable.
verify: $(SRC)/golf.asm $(ROM)
	@sh tools/verify_build.sh $(SRC)/golf.asm $(ROM) $(ORG)

# Lo que el reensamblado NO puede cazar: que unos datos se esten leyendo como
# codigo. El binario sale identico igual, porque los bytes no cambian; lo unico
# que cambia es lo que decimos de ellos.
sanity: $(WORK)/golf.trace.json
	@echo "=================================================================="
	@echo " ningun byte declarado como datos puede salir como codigo"
	@echo "=================================================================="
	@python3 tools/check_trace.py $(WORK)/golf.trace.json $(SRC)/golf.nocode
	@python3 tools/check_datos_como_codigo.py $(WORK) $(SRC)
	@echo "=================================================================="
	@echo " ningun punto de entrada puede caer dentro de una zona de datos"
	@echo "=================================================================="
	@python3 tools/check_entradas.py $(SRC)/golf.entries $(SRC)/golf.notes \
	        $(SRC)/golf.nocode
	@echo "=================================================================="
	@echo " ni un byte del cartucho sin asignar"
	@echo "=================================================================="
	@python3 tools/presupuesto.py $(WORK) $(SRC)

densidad:
	@python3 tools/densidad.py $(SRC)/golf.asm

test:
	@echo "=================================================================="
	@echo " Tests"
	@echo "=================================================================="
	@python3 -m unittest discover -s tests -v

# Dibuja los bloques de datos graficos declarados en el .notes, para MIRARLOS.
imagenes: $(ROM)
	@mkdir -p work/gfx
	python3 tools/dibuja.py $(ROM) $(ORG) $(SRC)/golf.notes work/gfx

# LA WEB
#
# Bilingue: el ingles en docs/ y el castellano en docs/es/. Las paginas se
# escriben en markdown y se convierten con md2html.py; la portada la monta
# make_web.py, que declara las cifras medidas de ESTE cartucho.
web: $(ROM)
	@test -f tools/graficos.py && python3 tools/graficos.py $(ROM) $(ORG) docs/imagenes || echo '  (aun no hay graficos.py)'
	python3 tools/md2html.py docs en
	python3 tools/md2html.py docs/es es
	python3 tools/make_web.py docs/imagenes docs/index.html en
	python3 tools/make_web.py docs/imagenes docs/es/index.html es
	python3 tools/check_enlaces.py docs

clean:
	rm -rf $(WORK)/golf.trace.json $(WORK)/golf.blocks


PYMUS ?= python3     # el que tenga numpy y lameenc
# La musica: el motor del cartucho ejecutado (tools/musica.py) a MP3
musica: $(ROM)
	$(PYMUS) tools/musica.py todas docs/audio
	$(PYMUS) tools/pagina_musica.py

.PHONY: musica all comprueba trace listado verify sanity test densidad imagenes web clean

wgottwalt-amiga-rom-split-amigaromsplit-.text:
// SPDX-License-Identifier: LGPL-3.0-or-later
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include "Args.hxx"

constexpr int32_t Rom256k = 256 * 1024;
constexpr int32_t Rom512k = 512 * 1024;
constexpr int32_t Rom1024k = 1024 * 1024;
constexpr auto Bin = std::ios::binary;

void printUsage(const char *app)
{
    std::cout << "AMIGA ROM split and endianness correction - create burnable ROMs\n"
              << "usage: " << app << " <options>\n"
              << "\n"
              << "options:\n"
              << "  -h, --help        this help screen\n"
              << "  -f, --file <f>    input file\n"
              << "  -s, --split       also create splitted files for 32Bit Amigas\n"
              << "  -x, --suffix <s>  use suffix (default: .bin)\n"
              << std::endl;
}

int32_t main(int32_t argc, char **argv)
{
    Args args(argc, argv, nullptr, printUsage);

    if (!args.help(true))
    {
        auto [fname_avail, fname] = args.opt('f', "file", true);
        auto [split_avail, _] = args.opt('s', "split");
        auto [suffix_avail, suffix] = args.opt('x', "suffix", true);
        std::string fname_l;
        std::string fname_h;

        if (!fname_avail)
        {
            std::cerr << "error: no input file given" << std::endl;
            return 1;
        }

        if (auto pos = fname.find_last_of('.'); pos != std::string::npos)
        {
            fname_l = fname.substr(0, pos);
            fname_h = fname.substr(0, pos);
        }
        else
        {
            fname_l = fname;
            fname_h = fname;
        }

        if (split_avail)
        {
            fname_l += "_low";
            fname_h += "_high";
        }

        if (suffix_avail)
        {
            if (suffix[0] == '.')
                suffix.erase(0, 1);

            fname_l += "." + suffix;
            fname_h += "." + suffix;
        }
        else
        {
            fname_l += ".bin";
            fname_h += ".bin";
        }

        if (std::ifstream ifile(fname, Bin); ifile.is_open() && ifile.good())
        {
            const auto size = ifile.seekg(0, std::ios::end).tellg();
            std::vector<char> buf;

            if ((size != Rom256k) && (size != Rom512k) && (size != Rom1024k))
            {
                std::cerr << "error: wrong ROM size (needs to be 256, 512 or 512 KiB)" << std::endl;
                return 1;
            }

            buf.resize(size, 0);
            ifile.seekg(0, std::ios::beg);
            ifile.read(buf.data(), size);

            if (split_avail)
            {
                if (std::ofstream ofile_l(fname_l, Bin), ofile_h(fname_h, Bin);
                    ofile_l.is_open() && ofile_l.good() && ofile_h.is_open() && ofile_h.good())
                {
                    for (int32_t r = 0; r < 2; ++r)
                    {
                        for (int32_t i = 0; i < size; i += 4)
                        {
                            ofile_h.put(buf[i + 1]).put(buf[i]);
                            ofile_l.put(buf[i + 3]).put(buf[i + 2]);
                        }
                    }

                    std::cout << "created '" << fname_l << "' and '" << fname_h << "'" << std::endl;
                }
                else
                {
                    std::cerr << "error: unable to open output files '" << fname_l << "' and/or '"
                              << fname_h << "'" << std::endl;
                    return 1;
                }
            }
            else
            {
                if (std::ofstream ofile_l(fname_l, Bin); ofile_l.is_open() && ofile_l.good())
                {
                    for (int32_t i = 0; i < size; i += 4)
                        ofile_l.put(buf[i + 1]).put(buf[i]).put(buf[i + 3]).put(buf[i + 2]);

                    std::cout << "created '" << fname_l << "'" << std::endl;
                }
                else
                {
                    std::cerr << "error: unable to open output file '" << fname_l << "'"
                              << std::endl;
                    return 1;
                }
            }
        }
        else
        {
            std::cerr << "error: unable to open ROM file '" << fname << "'" << std::endl;
            return 1;
        }
    }

    return 0;
}

